  let e=max(u.dims.w*.8,u.brushParams.x*.22);
  let g=vec3f(map(hit+vec3f(e,0,0))-map(hit-vec3f(e,0,0)),map(hit+vec3f(0,e,0))-map(hit-vec3f(0,e,0)),map(hit+vec3f(0,0,e))-map(hit-vec3f(0,0,e)));
