  wave+=waveBand(p.xz,vec2f(-.73,.683),2.71,amplitude*.14,time*.81,2.1);
  wave+=waveBand(p.xz,vec2f(.83,-.558),5.49,amplitude*.06*detailVisibility(p,5.49),time*.7,5.7);
